//! Integration tests for [`pkix_identity::verify_dns_name`].
//!
//! Oracle: DER fixtures generated by `tests/fixtures/gen.py` using
//! pyca/cryptography. See `tests/fixtures/README.md` for the SAN
//! contents of each fixture.
//!
//! The fixtures are self-signed leaf certificates; `pkix-identity` is
//! a pure-function library over a single `Certificate` and does not
//! validate chains, so no chain context is needed.

use der::Decode as _;
use pkix_identity::{verify_dns_name, IdentityError, MailboxName, ServerName};
use x509_cert::Certificate;

fn load(name: &str) -> Certificate {
    let path = format!("tests/fixtures/{name}");
    let der = std::fs::read(&path).unwrap_or_else(|e| panic!("fixture not found: {path}: {e}"));
    Certificate::from_der(&der).unwrap_or_else(|e| panic!("invalid DER in {path}: {e}"))
}

// ---------------------------------------------------------------------------
// Exact DNS name matching
// ---------------------------------------------------------------------------

#[test]
fn exact_dns_match() {
    let cert = load("san-exact-dns.der");
    let name = ServerName::dns_name("www.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn exact_dns_mismatch_returns_no_matching_san() {
    let cert = load("san-exact-dns.der");
    let name = ServerName::dns_name("api.example.com").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn exact_dns_match_is_case_insensitive() {
    let cert = load("san-exact-dns.der");
    let name = ServerName::dns_name("WWW.example.COM").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn mixed_case_san_matches_lowercase_target() {
    // SAN entry is "Host.Example.COM"; target is "host.example.com".
    let cert = load("san-mixed-case.der");
    let name = ServerName::dns_name("host.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

// ---------------------------------------------------------------------------
// Wildcard SANs (RFC 6125 §6.4.3)
// ---------------------------------------------------------------------------

#[test]
fn wildcard_matches_single_label() {
    let cert = load("san-wildcard-dns.der");
    let name = ServerName::dns_name("foo.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn wildcard_does_not_match_apex() {
    let cert = load("san-wildcard-dns.der");
    let name = ServerName::dns_name("example.com").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn wildcard_does_not_span_multiple_labels() {
    let cert = load("san-wildcard-dns.der");
    let name = ServerName::dns_name("a.b.example.com").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::NoMatchingSan)
    );
}

// ---------------------------------------------------------------------------
// Multi-entry SAN
// ---------------------------------------------------------------------------

#[test]
fn multi_san_matches_any_dns_entry() {
    let cert = load("san-multi-dns.der");
    // First DNS entry.
    let n1 = ServerName::dns_name("www.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &n1), Ok(()));
    // Second DNS entry.
    let n2 = ServerName::dns_name("api.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &n2), Ok(()));
    // Wildcard entry.
    let n3 = ServerName::dns_name("img.cdn.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &n3), Ok(()));
    // Not present.
    let n4 = ServerName::dns_name("other.example.com").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &n4),
        Err(IdentityError::NoMatchingSan)
    );
}

// ---------------------------------------------------------------------------
// IP literal SANs
// ---------------------------------------------------------------------------

#[test]
fn ipv4_san_matches() {
    let cert = load("san-ipv4.der");
    let name = ServerName::ip_address("192.0.2.5").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn ipv4_san_mismatch_rejects() {
    let cert = load("san-ipv4.der");
    let name = ServerName::ip_address("192.0.2.6").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn ipv4_target_does_not_match_dns_san() {
    // san-exact-dns.der has only DnsName entries; an IP target must not
    // match a DnsName.
    let cert = load("san-exact-dns.der");
    let name = ServerName::ip_address("192.0.2.5").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::NoMatchingSan)
    );
}

#[test]
fn ipv6_san_matches() {
    let cert = load("san-ipv6.der");
    let name = ServerName::ip_address("2001:db8::1").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn ipv6_san_matches_bracketed_input() {
    let cert = load("san-ipv6.der");
    let name = ServerName::ip_address("[2001:db8::1]").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn mixed_san_dispatch_by_target_type() {
    let cert = load("san-mixed.der");
    let dns_target = ServerName::dns_name("host.example.com").unwrap();
    assert_eq!(verify_dns_name(&cert, &dns_target), Ok(()));
    let ip_target = ServerName::ip_address("203.0.113.10").unwrap();
    assert_eq!(verify_dns_name(&cert, &ip_target), Ok(()));
    // A DNS-shaped target that happens to be the textual form of the
    // certificate's IP SAN entry MUST NOT match the IpAddress SAN — the
    // dispatch is keyed on the target type, not the textual form.
    // (`203.0.113.10` is a valid LDH string under our normalizer, so
    // dns_name accepts it; the match correctly fails.)
    let dns_lookalike = ServerName::dns_name("203.0.113.10").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &dns_lookalike),
        Err(IdentityError::NoMatchingSan)
    );
}

// ---------------------------------------------------------------------------
// IDN
// ---------------------------------------------------------------------------

#[test]
fn idn_u_label_target_matches_a_label_san() {
    let cert = load("san-idn-alabel.der");
    // Target is U-label form; pkix-identity must convert to A-label
    // before comparing against the SAN entry (which is already an
    // A-label per real-world CABF practice).
    let name = ServerName::dns_name("bücher.example").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

#[test]
fn idn_a_label_target_matches_a_label_san() {
    let cert = load("san-idn-alabel.der");
    let name = ServerName::dns_name("xn--bcher-kva.example").unwrap();
    assert_eq!(verify_dns_name(&cert, &name), Ok(()));
}

// ---------------------------------------------------------------------------
// Missing / CN-only
// ---------------------------------------------------------------------------

#[test]
fn missing_san_returns_missing_san() {
    let cert = load("san-missing.der");
    let name = ServerName::dns_name("anything.example.com").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &name),
        Err(IdentityError::MissingSan)
    );
}

#[test]
fn cn_only_rejected_with_missing_san() {
    // The CN attribute is `leaf`; we deliberately don't fall back to it.
    let cert = load("cn-only.der");
    let cn_target = ServerName::dns_name("leaf").unwrap();
    assert_eq!(
        verify_dns_name(&cert, &cn_target),
        Err(IdentityError::MissingSan)
    );
}

/// A certificate with two SubjectAltName extensions is rejected, not
/// resolved.
///
/// RFC 5280 §4.2 forbids duplicate extensions, and real CA software emits
/// them anyway. Reading the first instance and reading the last are both
/// defensible, which is the problem: an attacker who knows two
/// implementations choose differently puts a benign name in one SAN and
/// the target in the other, and the certificate is accepted by whichever
/// side it needs to fool.
///
/// So this matches `pkix-path`, which refuses such certificates during
/// path validation for the same stated reason — "accepting duplicates
/// would let one certificate mean different things to different
/// validators". A caller reaching `pkix-identity` through `pkix-chain`
/// never gets this far; the check exists so the standalone path agrees
/// rather than forming a differential between sibling crates.
///
/// The fixture's first SAN *does* contain the target, so a "first wins"
/// implementation would return `Ok`. That is what makes this a test of
/// the decision rather than of a parse failure.
#[test]
fn duplicate_san_extensions_are_rejected() {
    let cert = load("san-duplicate-ext.der");
    let name = ServerName::dns_name("www.example.com").expect("valid target");

    let err = verify_dns_name(&cert, &name)
        .expect_err("a certificate with two SAN extensions must be refused");
    assert_eq!(
        err,
        IdentityError::DuplicateSan,
        "the duplicate must be named as the problem, not reported as a name mismatch"
    );
}

/// The single-SAN sibling still passes, so the check above is not simply
/// breaking every certificate.
#[test]
fn a_single_san_extension_is_still_accepted() {
    let cert = load("san-exact-dns.der");
    let name = ServerName::dns_name("www.example.com").expect("valid target");
    verify_dns_name(&cert, &name).expect("one SAN extension is the normal case");
}

// ---------------------------------------------------------------------------
// Owned names as cache keys
// ---------------------------------------------------------------------------

/// The caller impact this closes out: a cache keyed by name.
///
/// `into_owned` already existed, so `'static` was reachable, but
/// neither name type derived `Hash` or `Ord` — so `'static` or not, it
/// could not key a `HashMap` or a `BTreeMap`. Both are needed: the
/// first for a `std` consumer, the second for a `no_std` one, where
/// `HashMap` is not available.
#[test]
fn an_owned_server_name_keys_both_kinds_of_map() {
    use std::collections::{BTreeMap, HashMap};

    let owned: ServerName<'static> = "www.example.com"
        .parse()
        .expect("FromStr yields a 'static name");
    let ip: ServerName<'static> = "192.0.2.1".parse().expect("IP literal");

    let mut hash: HashMap<ServerName<'static>, u32> = HashMap::new();
    hash.insert(owned.clone(), 1);
    hash.insert(ip.clone(), 2);
    let mut tree: BTreeMap<ServerName<'static>, u32> = BTreeMap::new();
    tree.insert(owned.clone(), 1);
    tree.insert(ip, 2);
    assert_eq!(hash.len(), 2);
    assert_eq!(tree.len(), 2);

    // The point of agreeing with Eq: a borrowed name finds the entry
    // stored under an owned one. Cow compares and hashes its contents,
    // so these are the same key.
    let borrowed = ServerName::dns_name("www.example.com").expect("valid");
    assert_eq!(borrowed, owned);
    assert_eq!(hash.get(&borrowed), Some(&1));
    assert_eq!(tree.get(&borrowed), Some(&1));
}

/// The same for mailboxes, including the case folding: a cache must
/// not hold two entries for one mailbox.
#[test]
fn an_owned_mailbox_name_keys_both_kinds_of_map() {
    use std::collections::{BTreeMap, HashMap};

    let owned: MailboxName<'static> = "User@Example.COM"
        .parse()
        .expect("FromStr yields a 'static mailbox");

    let mut hash: HashMap<MailboxName<'static>, u32> = HashMap::new();
    hash.insert(owned.clone(), 1);
    let mut tree: BTreeMap<MailboxName<'static>, u32> = BTreeMap::new();
    tree.insert(owned.clone(), 1);

    // The domain is case-folded at parse and the local-part is not, so
    // this is the same mailbox and must be the same key.
    let again = MailboxName::parse("User@example.com").expect("valid");
    assert_eq!(again, owned);
    assert_eq!(hash.get(&again), Some(&1));
    assert_eq!(tree.get(&again), Some(&1));

    // A different local-part is a different mailbox: the local-part is
    // case-sensitive per RFC 5321 §2.4.
    let other = MailboxName::parse("user@example.com").expect("valid");
    assert_ne!(other, owned);
    assert_eq!(hash.get(&other), None);
}
